{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C11", "C28", "C36", "C42", "C06", "C16", "C32", "C20", "C23", "C26", "C07", "C55"],
  "contradictory_card_ids": ["C25", "C09"],
  "prediction_basis_card_ids": ["C11", "C28", "C36", "C42", "C23", "C26", "C07", "C55"],
  "claims": [
    {
      "claim": "Omadacycline, a structurally related tetracycline derivative, has measured oral bioavailability of 34.5% in healthy adults after a 300 mg fasted oral dose, with 300 mg oral bioequivalent to 100 mg IV.",
      "card_ids": ["C11", "C28", "C36", "C42"]
    },
    {
      "claim": "Tetracycline, the parent scaffold, has reported human oral bioavailability of 75%, >70%, and 80–90%.",
      "card_ids": ["C23", "C26", "C07"]
    },
    {
      "claim": "New L3 oral exposure records for tetracycline show substantial systemic exposure after oral dosing (AUC0-inf 67.4 µg·h/mL after 500 mg), consistent with meaningful oral absorption.",
      "card_ids": ["C55"]
    },
    {
      "claim": "The 0.5% F omadacycline record is formulation-specific (slow dissolution tablet) and does not overturn the 34.5% F value; generic low-bioavailability statements for tetracyclines are contradicted by quantitative records.",
      "card_ids": ["C25", "C09"]
    },
    {
      "claim": "Low-F or low-exposure records for loperamide, butorphanol, ganciclovir, sulpiride, levosulpiride, DHE, DA-8010, and DHEC are structurally unrelated to the tetracycline query and do not provide transferable evidence for F <20%.",
      "card_ids": ["C02", "C15", "C33", "C10", "C17", "C31", "C35", "C04", "C03", "C27", "C08", "C13", "C18", "C29", "C58", "C60", "C63", "C66"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C55", "C56", "C57"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C58", "C60", "C61", "C62", "C63", "C64", "C65", "C66"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for the query molecule itself.",
    "Structural differences between the query (7-fluoro, 9-pyrrolidinoacetamido) and omadacycline/tetracycline may alter absorption and first-pass; transfer is inferred, not measured.",
    "No formulation, dose, or prandial condition is specified for the query.",
    "Physicochemical prior suggests low permeability, but no measured absorption, efflux, or clearance data for the query are available.",
    "L3 exposure records for DHE, DA-8010, and DHEC are not applicable to the tetracycline scaffold and do not inform the query endpoint."
  ],
  "decision_summary": "Predicted high because the most transferable experimental contexts are tetracycline-class molecules with F >=20% (omadacycline 34.5%; tetracycline 75%), and new L3 oral exposure records for tetracycline are consistent with meaningful oral absorption. The physicochemical low-F prior and formulation-specific low records are acknowledged but do not constitute affirmative threshold-relevant evidence for F <20%; unresolved uncertainty is reflected in moderate confidence and evidence gaps."
}

